#!/usr/bin/env python3
"""Build the main/trace, SDK and design sites without generated files in source."""
import argparse
import json
from pathlib import Path
import shutil
import subprocess
import sys
import tempfile
import yaml
from urllib.parse import urlsplit
from site_paths import localize_site

ROOT = Path(__file__).resolve().parents[2]


def published_nav(nav):
    """Turn another site's Markdown entries into links within the combined site."""
    if isinstance(nav, list):
        return [published_nav(item) for item in nav]
    if isinstance(nav, dict):
        return {title: published_nav(value) for title, value in nav.items()}
    if isinstance(nav, str) and nav.endswith('.md') and not nav.startswith(('/', 'http:', 'https:')):
        path = Path(nav)
        destination = path.parent if path.name == 'index.md' else path.with_suffix('')
        return '/' if str(destination) == '.' else '/' + destination.as_posix() + '/'
    return nav


def section_nav(nav, child_url, child_nav):
    """Expand the active subproject under Engineering, retaining the three tabs."""
    if nav == child_url:
        return child_nav
    if isinstance(nav, list):
        return [section_nav(item, child_url, child_nav) for item in nav]
    if isinstance(nav, dict):
        return {title: section_nav(value, child_url, child_nav) for title, value in nav.items()}
    return nav


def main():
    p = argparse.ArgumentParser(description=__doc__)
    p.add_argument('--out', type=lambda v: Path(v).resolve(), required=True)
    p.add_argument('--site-url', default='http://127.0.0.1:8010/', help='Base URL for local preview/canonical links')
    args = p.parse_args()
    url = urlsplit(args.site_url)
    if url.scheme not in ('http', 'https') or not url.netloc or url.query or url.fragment:
        p.error('--site-url must be an HTTP(S) site base URL without query or fragment')
    if args.out == ROOT or args.out in ROOT.parents or ROOT in args.out.parents:
        p.error('--out must be outside the source repository and cannot contain it')
    if args.out.exists() and any(args.out.iterdir()) and not (args.out/'.opencute-docs-site').is_file():
        p.error('--out is nonempty and is not a site previously generated by this tool')
    args.out.mkdir(parents=True, exist_ok=True)
    logs = args.out.parent / (args.out.name + '-logs')
    logs.mkdir(exist_ok=True)
    results = []
    with tempfile.TemporaryDirectory(prefix='opencute-doc-') as temporary:
        stage = Path(temporary)
        shutil.copytree(ROOT/'doc/docs', stage/'docs')
        shutil.copytree(ROOT/'trace/docs', stage/'docs/trace')
        config = yaml.safe_load((ROOT/'doc/mkdocs.yml').read_text())
        config['docs_dir'] = str(stage/'docs')
        config['site_dir'] = str(args.out)
        config['site_url'] = args.site_url.rstrip('/')+'/'
        (stage/'mkdocs.yml').write_text(yaml.safe_dump(config, allow_unicode=True, sort_keys=False))
        sites = [('main', stage/'mkdocs.yml', args.out),
                 ('sdk', ROOT/'doc/sdk-doc/mkdocs.yml', args.out/'sdk'),
                 ('design', ROOT/'doc/design-doc/mkdocs.yml', args.out/'design')]
        for name, config_path, destination in sites:
            if name != 'main':
                # Only read strings in nav/features here. The inherited design config
                # contains Python-tagged Markdown extensions, loaded by MkDocs itself.
                child = yaml.load(config_path.read_text(), Loader=yaml.BaseLoader)
                child_nav = [item for item in child['nav']
                             if item != {'OpenCUTE 主文档': '/'}]
                features = list(dict.fromkeys(child['theme'].get('features', []) +
                                             ['navigation.tabs', 'navigation.tabs.sticky',
                                              'navigation.sections', 'navigation.indexes']))
                docs_dir = config_path.parent/'docs'
                overrides = {}
                if name == 'design':
                    # The parent site owns shared browser dependencies. Stage the
                    # selected design revision unchanged, then supply local Mermaid.
                    docs_dir = stage/'design-docs'
                    shutil.copytree(config_path.parent/'docs', docs_dir)
                    vendor = Path('assets/vendor/mermaid-10.4.0')
                    shutil.copytree(ROOT/'doc/docs'/vendor, docs_dir/vendor, dirs_exist_ok=True)
                    plugins = []
                    for plugin in child.get('plugins', []):
                        if plugin == 'mermaid2' or isinstance(plugin, dict) and 'mermaid2' in plugin:
                            options = dict(plugin.get('mermaid2') or {}) if isinstance(plugin, dict) else {}
                            plugins.append({'mermaid2': {**options, 'javascript': (vendor/'mermaid.min.js').as_posix()}})
                        else:
                            plugins.append(plugin)
                    overrides['plugins'] = plugins
                wrapper = stage/(name+'-config.yml')
                wrapper.write_text(yaml.safe_dump({
                    'INHERIT': str(config_path),
                    'site_name': child['site_name'],
                    'docs_dir': str(docs_dir),
                    'site_url': args.site_url.rstrip('/')+'/'+name+'/',
                    'theme': {'features': features},
                    'nav': section_nav(published_nav(config['nav']), '/'+name+'/', child_nav),
                    **overrides,
                }, allow_unicode=True, sort_keys=False))
                config_path = wrapper
            cmd = [sys.executable, '-m', 'mkdocs', 'build', '--strict',
                   '--config-file', str(config_path), '--site-dir', str(destination)]
            with (logs/(name+'.log')).open('w') as log:
                run = subprocess.run(cmd, stdout=log, stderr=log)
            results.append({'site': name, 'exit': run.returncode, 'log': str(logs/(name+'.log'))})
            print(json.dumps(results[-1]), flush=True)
        if not any(r['exit'] for r in results):
            # Cross-site links such as /sdk/ must also work under /CUTE/ on Pages.
            localize_site(args.out, args.site_url)
            command = [sys.executable, str(ROOT/'tools/docs/check_links.py'), str(args.out),
                       '--report', str(logs/'links.json')]
            with (logs/'links.log').open('w') as log:
                run = subprocess.run(command, stdout=log, stderr=log)
            results.append({'site': 'cross-site-links', 'exit': run.returncode, 'log': str(logs/'links.log')})
        (logs/'results.json').write_text(json.dumps(results, indent=2)+'\n')
    (args.out/'.opencute-docs-site').write_text('Generated by tools/docs/build_docs.py\n')
    return int(any(r['exit'] for r in results))


if __name__ == '__main__':
    raise SystemExit(main())
